import { Controller, Get, Post, Put, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
// 가정: 승인된 결의서는 approval_status = '승인' 인 결의서로 본다.
const APPROVED_STATUS = '승인';
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function requireId(value: unknown, label: string): number {
  const n = Number(value);
  if (value === undefined || value === null || value === '' || !Number.isInteger(n) || n <= 0) {
    throw invalid(label + '을(를) 확인해 주세요.');
  }
  return n;
}

function requireDate(value: unknown, label: string): string {
  if (typeof value !== 'string' || !DATE_PATTERN.test(value)) {
    throw invalid(label + '은(는) YYYY-MM-DD 형식이어야 합니다.');
  }
  return value;
}

function requireAmount(value: unknown): number {
  const n = Number(value);
  if (value === undefined || value === null || value === '' || !Number.isFinite(n) || n <= 0) {
    throw invalid('집행금액은 0보다 큰 숫자여야 합니다.');
  }
  return n;
}

function optionalDate(value: unknown, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  return requireDate(value, label);
}

@Controller('api/v1')
export class FnSfr00404Controller {
  @Get('/fund-executions')
  async listFundExecutions(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const from = optionalDate(query.executionDateFrom, '집행 일자 시작');
    const to = optionalDate(query.executionDateTo, '집행 일자 종료');
    let resolutionId: number | null = null;
    if (query.expenseResolutionId !== undefined && query.expenseResolutionId !== null && query.expenseResolutionId !== '') {
      resolutionId = requireId(query.expenseResolutionId, '결의서');
    }
    const pageNo = query.page === undefined || query.page === '' ? 0 : Number(query.page);
    let size = query.size === undefined || query.size === '' ? DEFAULT_SIZE : Number(query.size);
    if (!Number.isInteger(pageNo) || pageNo < 0 || !Number.isInteger(size) || size < 1) {
      throw invalid('page, size 값을 확인해 주세요.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    return transaction(async (db) => {
      const where = `
        WHERE (CAST(:from AS date) IS NULL OR execution_date >= CAST(:from AS date))
          AND (CAST(:to AS date) IS NULL OR execution_date <= CAST(:to AS date))
          AND (CAST(:resolutionId AS bigint) IS NULL OR expense_resolution_id = CAST(:resolutionId AS bigint))`;
      const filter = { from, to, resolutionId };
      const counts = await db.query(`SELECT COUNT(*) AS "total" FROM fund_execution` + where, filter);
      const items = await db.query(
        `SELECT fund_execution_id AS "fundExecutionId",
                expense_resolution_id AS "expenseResolutionId",
                partner_account_id AS "partnerAccountId",
                execution_date AS "executionDate",
                execution_amount AS "executionAmount"
           FROM fund_execution` + where + `
          ORDER BY fund_execution_id DESC
          LIMIT :size OFFSET :offset`,
        { ...filter, size, offset: pageNo * size },
      );
      return { items, page: pageNo, size, total: Number(counts[0].total) };
    });
  }

  @Post('/fund-executions')
  @HttpCode(200)
  async createFundExecution(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const expenseResolutionId = requireId(data.expenseResolutionId, '결의서');
    // 가정: 집행 시 거래처 계좌는 필수 (fund_execution.partner_account_id NOT NULL)
    const partnerAccountId = requireId(data.partnerAccountId, '거래처 계좌');
    const executionDate = requireDate(data.executionDate, '집행일자');
    const executionAmount = requireAmount(data.executionAmount);
    return transaction(async (db) => {
      const resolutions = await db.query(
        `SELECT amount AS "amount", approval_status AS "status"
           FROM expense_resolution
          WHERE expense_resolution_id = CAST(:id AS bigint)`,
        { id: expenseResolutionId },
      );
      if (resolutions.length === 0) {
        throw new ApiError(404, 'EXPENSE_RESOLUTION_NOT_FOUND', '대상 결의서가 없습니다.');
      }
      if (resolutions[0].status !== APPROVED_STATUS) {
        throw new ApiError(409, 'RESOLUTION_NOT_APPROVED', '승인되지 않은 결의서에는 자금집행을 등록할 수 없습니다.');
      }
      const accounts = await db.query(
        `SELECT partner_account_id FROM partner_account WHERE partner_account_id = CAST(:id AS bigint)`,
        { id: partnerAccountId },
      );
      if (accounts.length === 0) {
        throw new ApiError(404, 'PARTNER_ACCOUNT_NOT_FOUND', '거래처 계좌가 없습니다.');
      }
      const sums = await db.query(
        `SELECT COALESCE(SUM(execution_amount), 0) AS "total"
           FROM fund_execution
          WHERE expense_resolution_id = CAST(:id AS bigint)`,
        { id: expenseResolutionId },
      );
      const used = Number(sums[0].total);
      if (used + executionAmount > Number(resolutions[0].amount)) {
        throw new ApiError(422, 'EXECUTION_AMOUNT_EXCEEDED', '집행 금액이 결의 금액을 초과합니다.');
      }
      const rows = await db.query(
        `INSERT INTO fund_execution
           (expense_resolution_id, partner_account_id, execution_date, execution_amount, created_at, updated_at)
         VALUES
           (CAST(:resolutionId AS bigint), CAST(:accountId AS bigint), CAST(:executionDate AS date), CAST(:amount AS numeric), now(), now())
         RETURNING fund_execution_id AS "fundExecutionId"`,
        { resolutionId: expenseResolutionId, accountId: partnerAccountId, executionDate, amount: executionAmount },
      );
      return { fundExecutionId: Number(rows[0].fundExecutionId) };
    });
  }

  @Put('/fund-executions/:fundExecutionId')
  async updateFundExecution(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const fundExecutionId = requireId(req.params['fundExecutionId'], '자금집행 ID');
    const data = checks.inputOf(req.body);
    // 가정: 집행 시 거래처 계좌는 필수 (fund_execution.partner_account_id NOT NULL)
    const partnerAccountId = requireId(data.partnerAccountId, '거래처 계좌');
    const executionDate = requireDate(data.executionDate, '집행일자');
    const executionAmount = requireAmount(data.executionAmount);
    return transaction(async (db) => {
      const current = await db.query(
        `SELECT f.expense_resolution_id AS "resolutionId", r.amount AS "amount"
           FROM fund_execution f
           JOIN expense_resolution r ON r.expense_resolution_id = f.expense_resolution_id
          WHERE f.fund_execution_id = CAST(:id AS bigint)`,
        { id: fundExecutionId },
      );
      if (current.length === 0) {
        throw new ApiError(404, 'FUND_EXECUTION_NOT_FOUND', '자금집행이 없습니다.');
      }
      const accounts = await db.query(
        `SELECT partner_account_id FROM partner_account WHERE partner_account_id = CAST(:id AS bigint)`,
        { id: partnerAccountId },
      );
      if (accounts.length === 0) {
        throw new ApiError(404, 'PARTNER_ACCOUNT_NOT_FOUND', '거래처 계좌가 없습니다.');
      }
      const sums = await db.query(
        `SELECT COALESCE(SUM(execution_amount), 0) AS "total"
           FROM fund_execution
          WHERE expense_resolution_id = CAST(:resolutionId AS bigint)
            AND fund_execution_id <> CAST(:id AS bigint)`,
        { resolutionId: current[0].resolutionId, id: fundExecutionId },
      );
      if (Number(sums[0].total) + executionAmount > Number(current[0].amount)) {
        throw new ApiError(422, 'EXECUTION_AMOUNT_EXCEEDED', '집행 금액이 결의 금액을 초과합니다.');
      }
      await db.execute(
        `UPDATE fund_execution
            SET partner_account_id = CAST(:accountId AS bigint),
                execution_date = CAST(:executionDate AS date),
                execution_amount = CAST(:amount AS numeric),
                updated_at = now()
          WHERE fund_execution_id = CAST(:id AS bigint)`,
        { accountId: partnerAccountId, executionDate, amount: executionAmount, id: fundExecutionId },
      );
      return { fundExecutionId };
    });
  }

  @Delete('/fund-executions/:fundExecutionId')
  async deleteFundExecution(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const fundExecutionId = requireId(req.params['fundExecutionId'], '자금집행 ID');
    return transaction(async (db) => {
      const count = await db.execute(
        `DELETE FROM fund_execution WHERE fund_execution_id = CAST(:id AS bigint)`,
        { id: fundExecutionId },
      );
      if (count === 0) {
        throw new ApiError(404, 'FUND_EXECUTION_NOT_FOUND', '자금집행이 없습니다.');
      }
      return {};
    });
  }
}

