import { useState } from 'react';
import {
  call, useData, Num, DateText, Filters, Band, DataTable, Pager, Drawer, Pairs, Tiles,
  Form, Field, NumberInput, DateInput, LookupSelect, RefName, ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

type Mode = { kind: 'create' } | { kind: 'detail' | 'edit' | 'delete'; row: Row } | null;

const SIZE = 20;

export default function FnSfr00404Page({ role, notify }: PageProps) {
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [resolutionFilter, setResolutionFilter] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [pageNo, setPageNo] = useState(0);
  const [mode, setMode] = useState<Mode>(null);

  const [resolutionId, setResolutionId] = useState<number | string>('');
  const [accountId, setAccountId] = useState<number | string>('');
  const [date, setDate] = useState('');
  const [amount, setAmount] = useState<number | string>('');

  const list = useData<Page>(
    () => call<Page>('GET', '/fund-executions', role, undefined, { ...applied, page: pageNo, size: SIZE }),
    [applied, pageNo],
  );
  const rows = list.data?.items ?? [];
  const total = list.data?.total ?? 0;

  function search() {
    setPageNo(0);
    setApplied({
      executionDateFrom: from,
      executionDateTo: to,
      expenseResolutionId: resolutionFilter,
    });
  }

  function reset() {
    setFrom('');
    setTo('');
    setResolutionFilter('');
    setPageNo(0);
    setApplied({});
  }

  function openCreate() {
    setResolutionId('');
    setAccountId('');
    setDate('');
    setAmount('');
    setMode({ kind: 'create' });
  }

  function openEdit(row: Row) {
    setAccountId(row.partnerAccountId as number);
    setDate(String(row.executionDate ?? '').slice(0, 10));
    setAmount(row.executionAmount as number);
    setMode({ kind: 'edit', row });
  }

  function validate(needResolution: boolean) {
    if (needResolution && resolutionId === '') {
      throw new Error('결의서를 선택해 주세요.');
    }
    if (accountId === '') {
      throw new Error('거래처 계좌를 선택해 주세요.');
    }
    if (date === '') {
      throw new Error('집행일자를 입력해 주세요.');
    }
    if (amount === '') {
      throw new Error('집행금액을 입력해 주세요.');
    }
  }

  async function create() {
    validate(true);
    await call('POST', '/fund-executions', role, {
      expenseResolutionId: resolutionId,
      partnerAccountId: accountId,
      executionDate: date,
      executionAmount: amount,
    });
    notify('자금집행을 등록했습니다.');
    setMode(null);
    list.reload();
  }

  async function update(row: Row) {
    validate(false);
    await call('PUT', '/fund-executions/' + row.fundExecutionId, role, {
      partnerAccountId: accountId,
      executionDate: date,
      executionAmount: amount,
    });
    notify('자금집행을 수정했습니다.');
    setMode(null);
    list.reload();
  }

  async function remove(row: Row) {
    await call('DELETE', '/fund-executions/' + row.fundExecutionId, role);
    notify('자금집행을 삭제했습니다.');
    setMode(null);
    list.reload();
  }

  const columns = [
    { key: 'fundExecutionId', label: '자금집행 ID' },
    {
      key: 'expenseResolutionId',
      label: '결의서',
      render: (r: Row) => <RefName table="expense_resolution" role={role} value={r.expenseResolutionId} />,
    },
    {
      key: 'partnerAccountId',
      label: '거래처 계좌',
      render: (r: Row) => <RefName table="partner_account" role={role} value={r.partnerAccountId} />,
    },
    { key: 'executionDate', label: '집행일자', render: (r: Row) => <DateText value={r.executionDate} /> },
    { key: 'executionAmount', label: '집행금액', render: (r: Row) => <Num value={r.executionAmount} /> },
  ];

  const accountField = (
    <Field label="거래처 계좌" required>
      <LookupSelect table="partner_account" role={role} value={accountId} onChange={setAccountId} />
    </Field>
  );
  const dateField = (
    <Field label="집행일자" required>
      <DateInput value={date} onChange={setDate} />
    </Field>
  );
  const amountField = (
    <Field label="집행금액" required>
      <NumberInput value={amount} onChange={setAmount} />
    </Field>
  );

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>자금집행 건수</h2>
        <Tiles items={[['조회 결과', <Num value={total} />]]} />
      </section>
      <section className="box span-8">
        <h2>안내</h2>
        <p>승인된 결의서에 대해서만 집행을 등록할 수 있으며, 집행 합계는 결의 금액을 넘을 수 없습니다.</p>
      </section>
      <section className="box span-12">
        <h2>자금집행 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="집행 일자 시작">
            <DateInput value={from} onChange={setFrom} />
          </Field>
          <Field label="집행 일자 종료">
            <DateInput value={to} onChange={setTo} />
          </Field>
          <Field label="결의서">
            <LookupSelect
              table="expense_resolution"
              role={role}
              value={resolutionFilter}
              onChange={setResolutionFilter}
              placeholder="전체"
            />
          </Field>
        </Filters>
        <Band total={total}>
          <button type="button" onClick={openCreate}>자금집행 등록</button>
        </Band>
        {list.error && <ErrorText text={list.error} />}
        <DataTable
          columns={columns}
          rows={rows}
          onRowClick={(row) => setMode({ kind: 'detail', row })}
          empty="자금집행 내역이 없습니다."
        />
        <Pager page={pageNo} size={SIZE} total={total} onPage={setPageNo} />
      </section>

      {mode && mode.kind === 'create' && (
        <Drawer title="자금집행 등록" onClose={() => setMode(null)}>
          <Form onSubmit={create} submit="등록">
            <Field label="결의서" required>
              <LookupSelect table="expense_resolution" role={role} value={resolutionId} onChange={setResolutionId} />
            </Field>
            {accountField}
            {dateField}
            {amountField}
          </Form>
        </Drawer>
      )}

      {mode && mode.kind === 'detail' && (
        <Drawer title="자금집행 상세" onClose={() => setMode(null)}>
          <Pairs
            items={[
              ['자금집행 ID', String(mode.row.fundExecutionId)],
              ['결의서', <RefName table="expense_resolution" role={role} value={mode.row.expenseResolutionId} />],
              ['거래처 계좌', <RefName table="partner_account" role={role} value={mode.row.partnerAccountId} />],
              ['집행일자', <DateText value={mode.row.executionDate} />],
              ['집행금액', <Num value={mode.row.executionAmount} />],
            ]}
          />
          <button type="button" onClick={() => openEdit((mode as { row: Row }).row)}>수정</button>
          <button type="button" onClick={() => setMode({ kind: 'delete', row: (mode as { row: Row }).row })}>삭제</button>
        </Drawer>
      )}

      {mode && mode.kind === 'edit' && (
        <Drawer title="자금집행 수정" onClose={() => setMode(null)}>
          <Form onSubmit={() => update((mode as { row: Row }).row)} submit="수정">
            {accountField}
            {dateField}
            {amountField}
          </Form>
        </Drawer>
      )}

      {mode && mode.kind === 'delete' && (
        <Drawer title="자금집행 삭제" onClose={() => setMode(null)}>
          <Form
            onSubmit={() => remove((mode as { row: Row }).row)}
            submit="삭제"
            danger
            note="이 자금집행을 삭제합니다. 계속할까요?"
          />
        </Drawer>
      )}
    </div>
  );
}
